import { Record } from "../fable_modules/fable-library-js.4.24.0/Types.js";
import { record_type, string_type } from "../fable_modules/fable-library-js.4.24.0/Reflection.js";

export class Photo extends Record {
    constructor(Category, Filename, Url, Caption) {
        super();
        this.Category = Category;
        this.Filename = Filename;
        this.Url = Url;
        this.Caption = Caption;
    }
}

export function Photo_$reflection() {
    return record_type("Pages.PhotobookContent.Photo", [], Photo, () => [["Category", string_type], ["Filename", string_type], ["Url", string_type], ["Caption", string_type]]);
}

